    raise AssertionError('Task 3: fahrenheit variable not found')

fahrenheit = globals()['fahrenheit']

if not isinstance(fahrenheit, list):
    raise AssertionError('Task 3: fahrenheit should be a list (use list() to convert the map result)')

expected = [32.0, 68.0, 86.0, 98.6, 212.0]

if len(fahrenheit) != len(expected):
    raise AssertionError(f'Task 3: Expected {len(expected)} values, got {len(fahrenheit)}')

for i, (actual, exp) in enumerate(zip(fahrenheit, expected)):
    if abs(actual - exp) > 0.1:
        raise AssertionError(f'Task 3: Value {i} should be approximately {exp}, got {actual}')

